function formatCents(cents) {
  // Format the magnitude and put the sign in front, so -50 -> "-0.50" (not "-1.-50").
  const sign = cents < 0 ? '-' : '';
  const abs = Math.abs(cents);
  const dollars = Math.floor(abs / 100);
  const rest = abs % 100;
  return `${sign}${dollars}.${String(rest).padStart(2, '0')}`;
}

